SET @sog_sql := IF(@sog_apply_ready AND @sog_apply_target_state='ABSENT', 'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`semester_offering_reviews` (`semester_offering_review_id` INT NOT NULL AUTO_INCREMENT,`semester_offering_request_id` INT NOT NULL,`submission_version` INT NOT NULL,`status` VARCHAR(16) NOT NULL DEFAULT ''pending'',`reviewed_by_user_id` INT NULL,`reviewed_at` DATETIME NULL,`reason` VARCHAR(1000) NULL,`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`semester_offering_review_id`),UNIQUE KEY `uq_sorv_request_version` (`semester_offering_request_id`,`submission_version`),KEY `idx_sorv_status` (`status`,`reviewed_at`),CONSTRAINT `chk_sorv_version` CHECK (`submission_version` > 0),CONSTRAINT `chk_sorv_status` CHECK (`status` IN (''pending'',''approved'',''returned'')),CONSTRAINT `chk_sorv_provenance` CHECK ((`status`=''pending'' AND `reviewed_by_user_id` IS NULL AND `reviewed_at` IS NULL AND `reason` IS NULL) OR (`status`=''approved'' AND `reviewed_by_user_id` IS NOT NULL AND `reviewed_at` IS NOT NULL AND `reason` IS NULL) OR (`status`=''returned'' AND `reviewed_by_user_id` IS NOT NULL AND `reviewed_at` IS NOT NULL AND CHAR_LENGTH(TRIM(`reason`))>0)),CONSTRAINT `fk_sorv_request` FOREIGN KEY (`semester_offering_request_id`) REFERENCES `alrowad_uni_rust`.`semester_offering_requests` (`semester_offering_request_id`) ON UPDATE RESTRICT ON DELETE RESTRICT,CONSTRAINT `fk_sorv_reviewer` FOREIGN KEY (`reviewed_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`) ON UPDATE RESTRICT ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=''Owned by semester-offering-governance-phase1; immutable scientific review per submission version''', 'SELECT ''PHASE1_DDL'' report_section, ''SKIPPED'' result');
