SET @sog_sql := IF(@sog_apply_ready AND @sog_apply_target_state='ABSENT', 'CREATE TABLE IF NOT EXISTS `alrowad_uni_rust`.`semester_offering_events` (`semester_offering_event_id` INT NOT NULL AUTO_INCREMENT,`semester_offering_request_id` INT NOT NULL,`submission_version` INT NOT NULL DEFAULT 0,`event_type` VARCHAR(32) NOT NULL,`actor_user_id` INT NOT NULL,`note` VARCHAR(1000) NULL,`occurred_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`semester_offering_event_id`),KEY `idx_soe_request_time` (`semester_offering_request_id`,`occurred_at`),KEY `idx_soe_type_time` (`event_type`,`occurred_at`),CONSTRAINT `chk_soe_version` CHECK (`submission_version` >= 0),CONSTRAINT `chk_soe_type` CHECK (`event_type` IN (''prepared'',''updated'',''deselected'',''submitted'',''resubmitted'',''scientific_returned'',''scientific_approved'',''materialized'')),CONSTRAINT `fk_soe_request` FOREIGN KEY (`semester_offering_request_id`) REFERENCES `alrowad_uni_rust`.`semester_offering_requests` (`semester_offering_request_id`) ON UPDATE RESTRICT ON DELETE RESTRICT,CONSTRAINT `fk_soe_actor` FOREIGN KEY (`actor_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`) ON UPDATE RESTRICT ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT=''Owned by semester-offering-governance-phase1; append-only transition history''', 'SELECT ''PHASE1_DDL'' report_section, ''SKIPPED'' result');
