SET @sog_sql := IF(@sog_apply_ready, 'INSERT INTO `alrowad_uni_rust`.`permissions` (`module_id`,`permission_code`,`permission_name`,`description`,`is_active`,`created_at`,`updated_at`) SELECT m.module_id,s.permission_code,s.permission_name,s.description,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM `alrowad_uni_rust`.`system_modules` m JOIN (SELECT ''course_offerings.semester_governance.view'' permission_code,''Semester Offering Governance View'' permission_name,''View semester offering governance'' description UNION ALL SELECT ''course_offerings.semester_governance.manage'',''Semester Offering Governance Manage'',''Prepare and submit semester offerings as Dean'' UNION ALL SELECT ''course_offerings.semester_governance.review_scientific'',''Semester Offering Scientific Review'',''Approve or return semester offerings as Scientific VP'') s WHERE m.module_code=''courses'' AND m.is_active=1 AND NOT EXISTS (SELECT 1 FROM `alrowad_uni_rust`.`permissions` p WHERE p.permission_code=s.permission_code)', 'SELECT ''PHASE1_RBAC'' report_section,''SKIPPED'' result');
