SET @sog_sql := IF(@sog_apply_ready, 'INSERT INTO `alrowad_uni_rust`.`role_permissions` (`role_id`,`permission_id`,`granted_at`) SELECT r.role_id,p.permission_id,CURRENT_TIMESTAMP FROM `alrowad_uni_rust`.`roles` r JOIN `alrowad_uni_rust`.`permissions` p ON ((r.role_code=''dean'' AND p.permission_code IN (''course_offerings.semester_governance.view'',''course_offerings.semester_governance.manage'')) OR (r.role_code=''vice_president_scientific'' AND p.permission_code IN (''course_offerings.semester_governance.view'',''course_offerings.semester_governance.review_scientific''))) WHERE r.is_active=1 AND p.is_active=1 AND NOT EXISTS (SELECT 1 FROM `alrowad_uni_rust`.`role_permissions` rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id)', 'SELECT ''PHASE1_RBAC'' report_section,''SKIPPED'' result');
